 5	final class DirectedGraphBuilder {
 6	    private final List<List<Integer>> adjacencyList;
 7	    private final int[] indegree;
 8	
 9	    DirectedGraphBuilder(int vertexCount) {
10	        if (vertexCount < 0) {
11	            throw new IllegalArgumentException("vertexCount must be non-negative");
12	        }
13	
14	        adjacencyList = new ArrayList<>(vertexCount);
15	        indegree = new int[vertexCount];
16	        for (int vertex = 0; vertex < vertexCount; vertex++) {
17	            adjacencyList.add(new ArrayList<>());
18	        }
19	    }
20	
21	    DirectedGraphBuilder addEdge(int source, int destination) {
22	        DirectedGraph.validateVertexIndex(source, adjacencyList.size());
23	        DirectedGraph.validateVertexIndex(destination, adjacencyList.size());
24	        adjacencyList.get(source).add(destination);
25	        indegree[destination]++;
26	        return this;
27	    }
28	
29	    DirectedGraph build() {
30	        List<List<Integer>> immutableAdjacencyList = new ArrayList<>(adjacencyList.size());
31	        for (List<Integer> neighbors : adjacencyList) {
32	            immutableAdjacencyList.add(Collections.unmodifiableList(new ArrayList<>(neighbors)));
33	        }
34	
35	        return new DirectedGraph(
36	                Collections.unmodifiableList(immutableAdjacencyList),
37	                indegree.clone());
38	    }
39	}

